// Textos do Cardslock Game em pt/en/es: habilidades, efeitos de local, mensagens do log e da tela.
import { strings } from "../i18n";
import type { AbilityKey, AbilityKind, ItemKey, ItemSlot, LocType, StatKey } from "./config";
import type { LogEntry, LogKey, Token } from "./engine";
import type { DeckLook } from "./deck";

type V = (v: number) => string;
type LocText = { label: string; text: (l: { v: number; n: number }) => string };
type Log = (e: LogEntry, name: (n: LogEntry["c"]) => string, ab: (k: AbilityKey) => string) => string;

export type GameText = {
  abilities: Record<AbilityKey, { name: string; text: V; master: () => string }>;
  stats: Record<StatKey, string>;
  /** Aprendiz, Profissional, Mestre. */
  levels: string[];
  kinds: Record<AbilityKind, string>;
  /** Explicação de cada selo de momento (no detalhe da carta). */
  kindTips: Record<AbilityKind, string>;
  locs: Record<LocType, LocText>;
  tokens: Record<Token, string>;
  /** Efeito de cada item (o nome fica em inglês, como no jogo e na API). */
  items: Record<ItemKey, V>;
  slots: Record<ItemSlot, string>;
  shop: {
    title: string; hint: string; tier: (t: number) => string; price: (n: number) => string; noSouls: string; fitCards: (n: number) => string; fitLoc: (l: string) => string;
    pick: string; picked: string; mine: string; ai: string; hidden: string; pickFirst: string; paid: (n: number) => string; label: (name: string, tier: number) => string;
    aim: (k: string) => string; undo: string; noTarget: string; on: (name: string) => string;
  };
  log: Record<LogKey, Log>;
  deck: {
    title: string; hint: string; count: (n: number, max: number) => string; avg: (n: number) => string; curve: string; search: string;
    random: string; clear: string; play: string; change: string; full: (max: number) => string; versions: string; alt: (n: number) => string; altPro: string;
    add: (name: string) => string; version: (name: string, hero: string) => string; empty: string; aiNote: string;
    defaultName: (n: number) => string; dupHero: (hero: string) => string; decks: string; newDeck: string; maxDecks: (n: number) => string; rename: string; duplicate: string; remove: string;
    cover: string; isCover: string; left: (n: number) => string; aiLeft: (n: number) => string; list: string; showList: (n: number) => string;
    open: (name: string) => string; take: (name: string) => string; addBtn: string; takeBtn: string; close: string; heroes: string; why: string;
    parts: { hero: (hero: string) => string; ovr: (ovr: number, half: boolean) => string; alt: string; floor: string; admin: string };
    costFrom: (hero: string) => string; vBonus: (at: number) => string; mastery: (stat: string, v: number, level: string) => string; emptyDeck: string; cards: (n: number) => string;
    moreHeroes: (n: number) => string; swapTitle: string; swapBtn: (hero: string, holder: string) => string; swapNote: string;
    look: string; looks: Record<DeckLook, string>;
    whichCard: (hero: string) => string; cardKind: { special: string; normal: string; alt: string };
  };
  ui: {
    title: string; loading: string; loadFail: string; needCards: (n: number) => string; you: string; ai: string;
    turn: (t: number, total: number) => string; phase: (p: number) => string; phaseHint: string; prio: (me: boolean) => string; prioHint: string; record: (w: number, l: number) => string; souls: (n: number) => string; aiSouls: (n: number) => string; players: string; decks: string;
    endTurn: string; newMatch: string; again: string; viewBoard: string; hint: string; hiddenLoc: string; revealsOn: (t: number) => string; next: (name: string) => string;
    cost: string; power: string; silenced: string; noAbility: string; tokenDesc: string; hand: string; arena: string;
    win: string; loss: string; draw: string; summary: (w: number, l: number, me: number, ai: number) => string; patron: string;
    toast: { souls: string; frozen: string; full: string; closed: string; minCost: string; turn: (t: number) => string };
    chips: { frozenMe: string; frozenAi: string; hookMe: string; hookAi: string; trapMe: string; trapAi: string; shieldMe: string; shieldAi: string; petriMe: string; petriAi: string; portal: string };
    status: { burn: string; stun: string; immune: string; chained: string; burrow: string; sleep: string; riposte: string; wolf: string; vuln: string; petri: string; unstop: string; chan: string; root: string; exec: string };
    act: {
      pickFoe: (c: string) => string; pickLoc: (c: string) => string; auto: string; undo: string; cancel: string;
      move: string; moveHint: (c: string) => string; mark: string; markHint: (c: string) => string; target: (c: string) => string; dest: (l: string) => string;
    };
    mastery: string; main: string; masterLine: string; locked: string; attrs: string; kw: string;
    yourSide: (loc: string) => string; aiSide: (loc: string) => string; facedown: string; playHere: (loc: string) => string;
    cardLabel: (name: string, cost: number, power: number) => string;
    /** O que cada status faz (caixa ao lado da carta ampliada). */
    statusTip: Record<keyof GameText["ui"]["status"], string>;
    aiHand: (n: number) => string; dropHere: (loc: string) => string;
    revealing: string; aim: string;
    audio: { title: string; sfx: string; music: string; mute: (what: string, on: boolean) => string; volume: (what: string) => string; credit: string }; fullscreen: (on: boolean) => string;
  };
};

const sg = (v: number) => (v >= 0 ? "+" : "−") + Math.abs(v);
const pl = (n: number, a: string, b: string) => (n === 1 ? a : b);

